def koç_mesaji_uret(puan, yuzdelik, toplam_net):
    """LGS sonuç ekranı için dinamik koç mesajı üretir."""
    if puan >= 490:
        return f"Muhteşem! {toplam_net:.1f} net ile zirve bandındasın. Hedef liseleri net tut, deneme ritmini bozma."
    if puan >= 470:
        return f"Çok güçlü bir profil ({yuzdelik}% dilim). Matematik ve Fen'de 1-2 net daha seni seçkin okullara taşır."
    if puan >= 450:
        return f"İyi bir temel var. Zayıf dersini tespit et; haftalık +3 net hedefi koy. Toplam {toplam_net:.1f} net."
    if puan >= 400:
        return f"Gelişim alanı açık. Günlük 90-120 soru ve 1 konu tekrarı ile 2-3 haftada sıçrama görürsün."
    if puan >= 350:
        return "Temel konuları tamamla. Önce Türkçe-Matematik-Fen üçlüsünde istikrar, sonra hız."
    return "Bugün planını sade tut: 1 konu + 30 soru + hata defteri. Küçük adımlar birikir."


def yks_ham_puan_tahmini(tyt_net, ayt_net, obp, alan="SAY"):
    """Basit YKS yerleştirme tarzı skor - eğitim simülasyonu."""
    obp_katki = float(obp or 0) * 0.6
    taban = 100 + float(tyt_net or 0) * 1.35 + float(ayt_net or 0) * 2.6 + obp_katki
    if alan == "DİL":
        taban = 100 + float(tyt_net or 0) * 1.2 + float(ayt_net or 0) * 3.0 + obp_katki
    return round(min(560.0, max(100.0, taban)), 2)


def kpss_puan_tahmini(gy_net, gk_net, tur="P3"):
    gy = float(gy_net or 0)
    gk = float(gk_net or 0)
    toplam = gy + gk
    if tur == "P1":
        agirlikli = gy * 0.70 + gk * 0.30
        return round(min(100.0, 40.0 + agirlikli), 2)
    if tur == "P2":
        agirlikli = gy * 0.60 + gk * 0.40
        return round(min(100.0, 40.0 + agirlikli), 2)
    if tur == "P93":
        return round(min(100.0, 41.2 + toplam * 0.49), 2)
    if tur == "P94":
        return round(min(100.0, 42.0 + toplam * 0.483), 2)
    agirlikli = gy * 0.50 + gk * 0.50
    return round(min(100.0, 40.0 + agirlikli), 2)


def su_hedef_bardak(kilo):
    """Günlük su hedefi (bardak ~250ml)."""
    litre = max(1.5, float(kilo or 60) * 0.035)
    return int(round(litre / 0.25))


def bmi_sinif(bmi):
    b = float(bmi or 0)
    if b < 18.5:
        return "Zayıf", "amber"
    if b < 25:
        return "Normal", "emerald"
    if b < 30:
        return "Fazla kilolu", "amber"
    return "Obezite riski", "rose"


def net_hedef_serisi(mevcut, hedef, gun):
    mevcut = float(mevcut or 0)
    hedef = float(hedef or 0)
    gun = max(1, int(gun or 1))
    artis = max(0.0, hedef - mevcut)
    gunluk = artis / gun
    seri = []
    for i in range(min(gun, 14)):
        seri.append(round(mevcut + gunluk * (i + 1), 2))
    return {"gunluk_artis": round(gunluk, 3), "seri_14": seri, "toplam_artis": round(artis, 2)}



