def hedef_bant_bul(puan):
    p = float(puan or 0)
    for b in LGS_HEDEF_BANTLARI:
        if p >= b["min_puan"]:
            return b
    return LGS_HEDEF_BANTLARI[-1]


def format_sira(n):
    try:
        n = int(n)
    except Exception:
        return str(n)
    return f"{n:,}".replace(",", ".")


def guvenli_float(deger, default=0.0, max_deger=None):
    try:
        x = float(str(deger).strip().replace(",", "."))
    except Exception:
        return float(default)
    if max_deger is not None:
        x = min(x, float(max_deger))
    return max(0.0, x)


