def paylasim_metni(tur, **kw):
    s = PAYLASIM_SABLONLARI.get(tur, "{msg}")
    try:
        return s.format(**kw)
    except Exception:
        return s


def guvenli_int(deger, max_deger):
    if deger is None:
        return 0
    metin = str(deger).strip()
    if metin == "":
        return 0
    try:
        sayi = int(float(metin))
    except (ValueError, TypeError):
        return 0
    return max(0, min(int(max_deger), sayi))


def lgs_yuzdelik_hesapla(puan, zorluk):
    p = float(puan)
    z = float(zorluk)
    if p >= 498.5:
        return 0.01
    if p >= 495.0:
        ham = 0.01 + ((498.5 - p) * 0.025 / z)
    elif p >= 490.0:
        ham = 0.10 + ((495.0 - p) * 0.085 / z)
    elif p >= 470.0:
        ham = 0.55 + ((490.0 - p) * 0.125 / z)
    elif p >= 450.0:
        ham = 3.05 + ((470.0 - p) * 0.210 / z)
    elif p >= 400.0:
        ham = 7.25 + ((450.0 - p) * 0.260 / z)
    elif p >= 350.0:
        ham = 20.25 + ((400.0 - p) * 0.340 / z)
    elif p >= 280.0:
        ham = 37.25 + ((350.0 - p) * 0.420 / z)
    else:
        ham = 66.65 + ((280.0 - p) * 0.180 / z)
    return round(max(0.01, min(99.90, ham)), 2)


def lgs_hesapla_tek_yil(form_data, secilen_yil="2026"):
    yil_key = str(secilen_yil) if str(secilen_yil) in LGS_YIL_PARAMETRELERI else "2026"
    param = LGS_YIL_PARAMETRELERI[yil_key]
    kullanici_verisi = {}
    netler = {}
    ders_detay = []
    toplam_net = 0.0
    toplam_agirlikli_net = 0.0
    dogru_toplam = 0
    yanlis_toplam = 0
    for d_meta in LGS_DERSLER:
        key = d_meta["key"]
        max_s = d_meta["max"]
        katsayi = d_meta["katsayi"]
        d = guvenli_int(form_data.get(f"{key}_d"), max_s)
        y = guvenli_int(form_data.get(f"{key}_y"), max_s)
        if d + y > max_s:
            y = max(0, max_s - d)
        bos = max(0, max_s - (d + y))
        net = round(max(0.0, d - (y / 3.0)), 2)
        kullanici_verisi[key] = {"d": d, "y": y, "bos": bos}
        netler[key] = net
        dogru_toplam += d
        yanlis_toplam += y
        toplam_net += net
        toplam_agirlikli_net += (net * katsayi)
        ders_detay.append({**d_meta, "d": d, "y": y, "bos": bos, "net": net})
    toplam_net = round(toplam_net, 2)
    toplam_agirlikli_net = round(toplam_agirlikli_net, 2)
    if dogru_toplam == 90 and yanlis_toplam == 0:
        puan = 500.0000
    else:
        taban = 195.0
        aralik = 305.0
        ham_puan = taban + ((toplam_agirlikli_net / 270.0) * aralik * param["carpan"])
        ust_sinir = 500.0 if toplam_net >= 89.99 else 499.85
        puan = max(195.0, min(ust_sinir, round(ham_puan, 4)))
    yuzdelik = lgs_yuzdelik_hesapla(puan, param["zorluk"])
    tahmini_sira = max(1, int(round((yuzdelik / 100.0) * param["aday"])))
    siralama_formatli = "{:,}".format(tahmini_sira).replace(",", ".")
    if yuzdelik <= 1.0:
        koc_mesaj = (f"Şampiyonlar Ligi Seviyesi! {yil_key} simülasyonuna göre {puan:.4f} puan ve %{yuzdelik} dilimle "
                     f"yaklaşık {siralama_formatli}. sıradasın. Galatasaray Lisesi, İstanbul Erkek, Kabataş, Ankara Fen ve "
                     f"Sakarya Cevat Ayhan Fen Lisesi kapıları sonuna kadar açık!")
    elif yuzdelik <= 4.0:
        koc_mesaj = (f"Üst Düzey Derece Adayı: {yil_key} simülasyonunda {puan:.4f} puan ve %{yuzdelik} dilimle "
                     f"yaklaşık {siralama_formatli}. sıradasın. Türkiye'nin seçkin Fen ve Proje Anadolu Liseleri hedefine çok yakın.")
    elif yuzdelik <= 15.0:
        koc_mesaj = (f"Güçlü Nitelikli Hedef: {yil_key} simülasyonuna göre {puan:.4f} puan ve %{yuzdelik} dilimle "
                     f"sıralaman {siralama_formatli} civarında. 4 katsayılı derslerdeki birkaç net artışı seni ilk %3'e taşır.")
    else:
        koc_mesaj = (f"Yükseliş Potansiyeli: {yil_key} simülasyonuna göre {puan:.4f} puan ve %{yuzdelik} dilimle "
                     f"sıralaman {siralama_formatli} civarında. Hata defteri ve düzenli deneme takibiyle hızla yükselebilirsin.")
    return {
        "yil": yil_key, "yil_notu": param["not"], "puan": f"{puan:.4f}", "puan_num": puan,
        "toplam_net": toplam_net, "toplam_agirlikli_net": toplam_agirlikli_net,
        "kullanici_verisi": kullanici_verisi, "netler": netler, "ders_detay": ders_detay,
        "dogru": int(dogru_toplam), "yanlis": int(yanlis_toplam),
        "bos": int(max(0, 90 - (dogru_toplam + yanlis_toplam))),
        "yuzdelik": yuzdelik, "siralama": siralama_formatli, "koc_mesaj": koc_mesaj
    }


def tum_yillar_karsilastir(form_data):
    sonuclar = []
    for yil in sorted(LGS_YIL_PARAMETRELERI.keys()):
        res = lgs_hesapla_tek_yil(form_data, yil)
        sonuclar.append({
            "yil": res["yil"], "yil_notu": res["yil_notu"], "puan": res["puan"],
            "puan_num": res["puan_num"], "yuzdelik": res["yuzdelik"],
            "siralama": res["siralama"], "toplam_net": res["toplam_net"],
        })
    return sonuclar


