@app.route("/", methods=["GET", "POST"])
def index():
    secilen_yil = request.form.get("yil", "2026") if request.method == "POST" else "2026"
    kaynak = request.form if request.method == "POST" else VARSAYILAN_FORM
    sonuc = lgs_hesapla_tek_yil(kaynak, secilen_yil)
    yillar_karsilastirma = tum_yillar_karsilastir(kaynak)
    uygun_okullar = []
    for ok in LISE_VERITABANI:
        fark = round(sonuc["puan_num"] - ok["taban_puan"], 2)
        uygun_okullar.append({**ok, "fark": fark})
    uygun_okullar.sort(key=lambda x: (0 if x["fark"] >= -6.0 else 1, abs(x["fark"])))
    sakarya_okullari = [o for o in uygun_okullar if o["sehir"] == "Sakarya"]
    return render_template_string(
        ENTERPRISE_HTML_TEMPLATE,
        sonuc=sonuc,
        yillar_karsilastirma=yillar_karsilastirma,
        uygun_okullar=uygun_okullar,
        sakarya_okullari=sakarya_okullari,
        dersler=LGS_DERSLER,
        tyt_dersler=TYT_DERSLER,
        ayt_dersler=AYT_DERSLER,
        kpss_dersler=KPSS_DERSLER,
        kpss_kadrolar=KPSS_KADROLAR,
        yillar=sorted(LGS_YIL_PARAMETRELERI.keys(), reverse=True),
        secilen_yil=secilen_yil,
        tum_iller=TUM_ILLER,
        universiteler=UNIVERSITE_VERITABANI,
        lise_sayisi=len(LISE_VERITABANI),
        univ_sayisi=len(UNIVERSITE_VERITABANI),
    )



@app.route("/api/saglik", methods=["POST"])
def api_saglik():
    data = request.get_json(silent=True) or {}
    cinsiyet = data.get("cinsiyet", "erkek")
    yas = float(data.get("yas") or 14)
    boy = float(data.get("boy") or 168)
    kilo = float(data.get("kilo") or 58)
    boy_m = boy / 100.0 if boy else 1.0
    bmi = kilo / (boy_m * boy_m)
    if bmi < 18.5:
        durum = "Zayıf"
    elif bmi < 25:
        durum = "Normal Kilolu"
    elif bmi < 30:
        durum = "Fazla Kilolu"
    else:
        durum = "Obezite Riski"
    ideal = (50 + 2.3 * ((boy / 2.54) - 60)) if cinsiyet == "erkek" else (45.5 + 2.3 * ((boy / 2.54) - 60))
    bmr = (10 * kilo + 6.25 * boy - 5 * yas + 5) if cinsiyet == "erkek" else (10 * kilo + 6.25 * boy - 5 * yas - 161)
    return jsonify({
        "bmi": round(bmi, 1),
        "durum": durum,
        "ideal_kg": round(max(40.0, ideal), 1),
        "su_litre": round(kilo * 0.035, 2),
        "kalori": int(round(bmr * 1.35))
    })



@app.route("/api/plan", methods=["POST"])
def api_plan():
    data = request.get_json(silent=True) or {}
    mevcut = float(data.get("mevcut") or 0)
    hedef = float(data.get("hedef") or 0)
    gun = int(float(data.get("gun") or 1))
    saat = float(data.get("saat") or 4)
    sonuc = net_hedef_serisi(mevcut, hedef, gun)
    sonuc["gunluk_soru"] = int(round(saat * 30))
    sonuc["toplam_saat"] = int(round(gun * saat))
    sonuc["bant"] = hedef_bant_bul(hedef * 5.2)  # kaba puan tahmini egitimsel
    return jsonify(sonuc)


