def lise_istatistik():
    turler = {}
    sehirler = {}
    for o in LISE_VERITABANI:
        turler[o["tur"]] = turler.get(o["tur"], 0) + 1
        sehirler[o["sehir"]] = sehirler.get(o["sehir"], 0) + 1
    return {
        "toplam": len(LISE_VERITABANI),
        "tur_dagilim": turler,
        "sehir_sayisi": len(sehirler),
        "en_cok_okul_sehir": max(sehirler.items(), key=lambda x: x[1])[0] if sehirler else None
    }


@app.route("/api/lise-istatistik")
def api_lise_istatistik():
    return jsonify(lise_istatistik())


@app.route("/api/univ-filtre")
def api_univ_filtre():
    q = (request.args.get("q") or "").lower().strip()
    tur = (request.args.get("tur") or "").upper().strip()
    son = []
    for u in UNIVERSITE_VERITABANI:
        if tur and u.get("puan_turu", "").upper() != tur:
            continue
        ad = (u.get("ad") or "").lower()
        sehir = (u.get("sehir") or "").lower()
        if q and q not in ad and q not in sehir:
            continue
        son.append(u)
        if len(son) >= 50:
            break
    return jsonify({"adet": len(son), "sonuclar": son})


@app.route("/api/kpss-filtre")
def api_kpss_filtre():
    q = (request.args.get("q") or "").lower().strip()
    min_taban = request.args.get("min")
    max_taban = request.args.get("max")
    try:
        min_v = float(min_taban) if min_taban not in (None, "") else None
    except Exception:
        min_v = None
    try:
        max_v = float(max_taban) if max_taban not in (None, "") else None
    except Exception:
        max_v = None
    son = []
    for k in KPSS_KADROLAR:
        blob = (k.get("unvan", "") + " " + k.get("kurum", "") + " " + k.get("tur", "")).lower()
        if q and q not in blob:
            continue
        taban = float(k.get("taban") or 0)
        if min_v is not None and taban < min_v:
            continue
        if max_v is not None and taban > max_v:
            continue
        son.append(k)
        if len(son) >= 80:
            break
    return jsonify({"adet": len(son), "sonuclar": son})


def net_to_kaba_lgs_puan(toplam_net):
    """Eğitim amaçlı kaba net->puan dönüşümü (tam motor ayrı)."""
    n = max(0.0, float(toplam_net or 0))
    return round(min(500.0, 100.0 + n * 4.15), 2)


@app.route("/api/net-puan", methods=["POST"])
def api_net_puan():
    data = request.get_json(silent=True) or {}
    net = float(data.get("net") or 0)
    return jsonify({"net": net, "kaba_puan": net_to_kaba_lgs_puan(net)})


